import sys

# Increase recursion depth for deep trees
sys.setrecursionlimit(200000)

def solve(n, edges, queries):
    from collections import defaultdict
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    sz = [0] * (n + 1)
    removed = [False] * (n + 1)

    def get_sz(u, p):
        sz[u] = 1
        for v in adj[u]:
            if v != p and not removed[v]:
                sz[u] += get_sz(v, u)
        return sz[u]

    def get_centroid(u, p, total_sz):
        for v in adj[u]:
            if v != p and not removed[v] and sz[v] > total_sz // 2:
                return get_centroid(v, u, total_sz)
        return u

    # Precompute distances using binary lifting for dist(u, v) = depth[u] + depth[v] - 2*depth[lca]
    # Or simpler: store dist to centroid ancestors
    centroid_parent = [0] * (n + 1)
    # dists[u] = {centroid_anc: dist, ...}
    dists = [{} for _ in range(n + 1)]

    def compute_dists(u, p, d, centroid):
        dists[u][centroid] = d
        for v in adj[u]:
            if v != p and not removed[v]:
                compute_dists(v, u, d + 1, centroid)

    def decompose(u, p):
        total = get_sz(u, -1)
        centroid = get_centroid(u, -1, total)
        centroid_parent[centroid] = p
        compute_dists(centroid, -1, 0, centroid)
        removed[centroid] = True
        for v in adj[centroid]:
            if not removed[v]:
                decompose(v, centroid)

    decompose(1, 0)

    results = []
    for u, v in queries:
        ans = float('inf')
        # Search for common centroid ancestor
        # All nodes in dists[u] are centroid ancestors
        for c, d1 in dists[u].items():
            if c in dists[v]:
                ans = min(ans, d1 + dists[v][c])
        results.append(str(ans))
    return "\n".join(results)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data: exit()
    idx = 0
    n = int(data[idx]); m = int(data[idx+1]); idx += 2
    edges = []
    for _ in range(m): edges.append((int(data[idx]), int(data[idx+1]))); idx += 2
    if idx < len(data):
        q_count = int(data[idx]); idx += 1
        queries = []
        for _ in range(q_count): queries.append((int(data[idx]), int(data[idx+1]))); idx += 2
        print(solve(n, edges, queries))

